export type PieceColor = 'w' | 'b'
export type PieceType = 'P' | 'N' | 'B' | 'R' | 'Q' | 'K'
export type PieceCode = `${PieceColor}${PieceType}`
export type BoardGrid = (PieceCode | null)[][]

