let cachedFonts: { name: string; data: Buffer; weight: 400 | 700; style: 'normal' }[] | null = null

function loadSatoriFonts(): { name: string; data: Buffer; weight: 400 | 700; style: 'normal' }[] {
  if (cachedFonts) return cachedFonts
  const primaryRegular = join(process.cwd(), 'assets', 'fonts', 'Inter.ttf')
  const primaryBold = join(process.cwd(), 'assets', 'fonts', 'Inter-Bold.ttf')
  const fallbackRegular = '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
  const fallbackBold = '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'

  const reg = existsSync(primaryRegular)
    ? readFileSync(primaryRegular)
    : readFileSync(fallbackRegular)
  const bold = existsSync(primaryBold)
    ? readFileSync(primaryBold)
    : existsSync(fallbackBold)
      ? readFileSync(fallbackBold)
      : reg

  cachedFonts = [
    { name: 'Inter', data: reg, weight: 400, style: 'normal' },
    { name: 'Inter', data: bold, weight: 700, style: 'normal' },
  ]
  return cachedFonts
}

export function getEloTier(elo: number): { title: string; badge: string; color: string } {
  if (elo >= 2000) return { title: 'Grandmaster', badge: '🔥 GM', color: '#ef4444' }
  if (elo >= 1800) return { title: 'International Master', badge: '💎 IM', color: '#38bdf8' }
  if (elo >= 1600) return { title: 'FIDE Master', badge: '👑 FM', color: '#f59e0b' }
  if (elo >= 1400) return { title: 'Candidate Master', badge: '🛡️ CM', color: '#a855f7' }
  if (elo >= 1200) return { title: 'Tactician', badge: '⚔️ Tactician', color: '#81b64c' }
  if (elo >= 1000) return { title: 'Club Player', badge: '♟️ Club', color: '#eaedd1' }
  return { title: 'Beginner', badge: '🌱 Novice', color: '#a09d98' }
}

